<?php
use App\Core\View; use App\Core\Auth;
$title=$title??'Byznio';
$path=parse_url($_SERVER['REQUEST_URI'],PHP_URL_PATH) ?: '/';
$isDashboard=in_array($path,['/','/dashboard'],true);
$public=in_array($path,['/login','/register'],true);
$workspaceLayout=null; $trialDaysLeft=null;
if(!$public && \App\Core\Auth::check()){
    $pdoLayout=\App\Core\Database::pdo();
    $stLayout=$pdoLayout->prepare('SELECT * FROM workspaces WHERE id=?'); $stLayout->execute([\App\Core\Auth::workspaceId()]); $workspaceLayout=$stLayout->fetch()?:null;
    $stTrial=$pdoLayout->prepare('SELECT status,trial_ends_at FROM subscriptions WHERE workspace_id=?'); $stTrial->execute([\App\Core\Auth::workspaceId()]); $trialLayout=$stTrial->fetch()?:null;
    if(($trialLayout['status']??'')==='trial' && !empty($trialLayout['trial_ends_at'])){ $diff=strtotime($trialLayout['trial_ends_at'])-time(); $trialDaysLeft=$diff>=0?(int)ceil($diff/86400):null; }
}
$niaBriefing=[];
if(!$public && \App\Core\Auth::check()){
    try{
        $widNia=\App\Core\Auth::workspaceId();
        $q=$pdoLayout->prepare('SELECT COUNT(*) FROM tasks WHERE workspace_id=? AND status="open" AND due_at IS NOT NULL AND date(due_at)=date("now")');$q->execute([$widNia]);$niaTodayTasks=(int)$q->fetchColumn();
        $q=$pdoLayout->prepare('SELECT COUNT(*) FROM documents WHERE workspace_id=? AND doc_type="invoice" AND payment_status!="paid" AND due_date<date("now")');$q->execute([$widNia]);$niaOverdue=(int)$q->fetchColumn();
        $q=$pdoLayout->prepare('SELECT COUNT(*) FROM jobs WHERE workspace_id=? AND status NOT IN ("done","cancelled")');$q->execute([$widNia]);$niaJobs=(int)$q->fetchColumn();
        $q=$pdoLayout->prepare('SELECT COALESCE(SUM(total_with_vat),0) FROM documents WHERE workspace_id=? AND doc_type="invoice" AND issue_date>=date("now","start of month")');$q->execute([$widNia]);$niaRevenue=(float)$q->fetchColumn();
        if($niaTodayTasks)$niaBriefing[]='Dnes máš '.$niaTodayTasks.' '.($niaTodayTasks===1?'otevřený úkol':'otevřené úkoly').'. Můžu je projít a seřadit podle priority.';
        if($niaOverdue)$niaBriefing[]='Po splatnosti je '.$niaOverdue.' '.($niaOverdue===1?'faktura':'faktury').'. Můžu připravit přehled a návrh dalšího kroku.';
        if($niaJobs)$niaBriefing[]='Aktivních zakázek je '.$niaJobs.'. Můžu zkontrolovat jejich termíny, rozpočty a další práci.';
        if(!$niaBriefing)$niaBriefing[]='Dnes zatím nevidím nic kritického. Můžu ti pomoci s fakturami, zákazníky, zakázkami nebo financemi.';
        $niaBriefing[]='Tento měsíc máš vystaveno za '.number_format($niaRevenue,0,',',' ').' Kč.';
    }catch(\Throwable $e){ $niaBriefing=['Jsem připravená pomoct. Řekni mi, co dnes potřebuješ vyřešit.']; }
}
$companyLogoUrl=null; if(!empty($workspaceLayout['logo_path'])){ $logoToken=hash_hmac('sha256',(string)\App\Core\Auth::workspaceId(),(string)\App\Core\Env::get('APP_KEY','')); $companyLogoUrl='/mail/logo/'.(int)\App\Core\Auth::workspaceId().'?token='.$logoToken; }
