const messages=<?=json_encode($niaBriefing,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES)?>;
let index=0,audioUnlocked=false,soundOn=false,pinned=false;
function speak(text){if(!soundOn||!audioUnlocked||!('speechSynthesis'in window))return;try{speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(text);u.lang='cs-CZ';u.rate=.98;u.pitch=1.04;const voices=speechSynthesis.getVoices();const cs=voices.find(v=>(v.lang||'').toLowerCase().startsWith('cs'));if(cs)u.voice=cs;fab.classList.add('talking');u.onend=()=>fab.classList.remove('talking');speechSynthesis.speak(u)}catch(e){}}
function showProactive(){if(!messages.length)return;const text=messages[index%messages.length];index++;bubbleText.textContent=text;bubble.classList.add('show');setTimeout(()=>{bubble.classList.remove('show')},6500)}
function open(){audioUnlocked=true;panel.classList.add('open');panel.setAttribute('aria-hidden','false');bubble.classList.remove('show');input.focus()}
function close(){panel.classList.remove('open');panel.setAttribute('aria-hidden','true');fab.classList.remove('talking','thinking')}
let drag={active:false,moved:false,pointerId:null,dx:0,dy:0};
fab.style.touchAction='none';
fab.addEventListener('pointerdown',e=>{if(panel.classList.contains('open')||pinned)return;drag.active=true;drag.moved=false;drag.pointerId=e.pointerId;const r=fab.getBoundingClientRect();drag.dx=e.clientX-r.left;drag.dy=e.clientY-r.top;fab.setPointerCapture?.(e.pointerId);e.preventDefault()});
fab.addEventListener('pointercancel',()=>{drag.active=false});
fab.addEventListener('pointermove',e=>{if(!drag.active)return;const r=fab.getBoundingClientRect();if(Math.abs(e.clientX-(r.left+drag.dx))>4||Math.abs(e.clientY-(r.top+drag.dy))>4)drag.moved=true;const size=r.width;fab.style.left=Math.max(8,Math.min(innerWidth-size-8,e.clientX-drag.dx))+'px';fab.style.top=Math.max(78,Math.min(innerHeight-size-92,e.clientY-drag.dy))+'px';fab.style.right='auto';fab.style.bottom='auto';e.preventDefault()});
fab.addEventListener('pointerup',e=>{if(!drag.active)return;drag.active=false;fab.releasePointerCapture?.(e.pointerId);if(drag.moved){try{localStorage.setItem('byznio_nia_pos',JSON.stringify({x:parseFloat(fab.style.left),y:parseFloat(fab.style.top)}))}catch(e){} }else e.preventDefault()});
fab.addEventListener('click',e=>{if(drag.moved){e.preventDefault();drag.moved=false;return}panel.classList.contains('open')?close():open()});
closeBtn?.addEventListener('click',close);
function applyPin(){if(pinBtn)pinBtn.textContent=pinned?'📍 Uvolnit Niu':'📌 Připnout Niu';fab.classList.toggle('nia-pinned',pinned)}
pinBtn?.addEventListener('click',()=>{pinned=!pinned;try{localStorage.setItem('byznio_nia_pinned',pinned?'1':'0')}catch(e){}applyPin()});
try{pinned=localStorage.getItem('byznio_nia_pinned')==='1';const saved=JSON.parse(localStorage.getItem('byznio_nia_pos')||'null');if(saved&&Number.isFinite(saved.x)&&Number.isFinite(saved.y)){fab.style.left=Math.max(8,Math.min(innerWidth-fab.offsetWidth-8,saved.x))+'px';fab.style.top=Math.max(78,Math.min(innerHeight-fab.offsetHeight-92,saved.y))+'px';fab.style.right='auto';fab.style.bottom='auto'}}catch(e){}applyPin();
async function ask(text){text=text.trim();if(!text)return;audioUnlocked=true;input.value='';answer.innerHTML='<span class="nia-typing"><i></i><i></i><i></i></span>';fab.classList.add('thinking','talking');try{const fd=new FormData(form);fd.set('prompt',text);const r=await fetch('/ai/ask',{method:'POST',body:fd,headers:{'X-Requested-With':'fetch'}});const j=await r.json();if(!j.ok)throw new Error(j.error||'');answer.textContent=j.answer||'Hotovo.';if(j.pending)answer.textContent+=' Připravený návrh čeká na potvrzení v chatu Nia.';speak(j.answer||'Hotovo.')}catch(e){answer.textContent='Teď se mi nepodařilo odpovědět. Zkus to prosím znovu.'}finally{fab.classList.remove('thinking');setTimeout(()=>fab.classList.remove('talking'),700)}}
form.addEventListener('submit',e=>{e.preventDefault();ask(input.value)});document.querySelectorAll('[data-nia-prompt]').forEach(b=>b.addEventListener('click',()=>ask(b.dataset.niaPrompt)));document.addEventListener('keydown',e=>{if(e.key==='Escape'&&panel.classList.contains('open'))close()});
soundBtn?.addEventListener('click',()=>{audioUnlocked=true;soundOn=!soundOn;soundBtn.textContent=soundOn?'🔊 Hlas Nii: zapnuto':'🔇 Hlas Nii: vypnuto';if(soundOn)speak('Hlas Nii je zapnutý. Budu tě upozorňovat na důležité věci.')});
setTimeout(showProactive,30000);
setInterval(()=>{if(!document.hidden&&!panel.classList.contains('open'))showProactive()},300000);
})();
</script>
<?php else: ?><?php include $file; ?><?php endif; ?>

</body></html>